def pick(service, ci, n=8):
    """اختيار ثابت لكل (خدمة، مدينة): يدوّر مجمّع الخدمة بحسب ترتيب المدينة."""
    pool = POOL[service]; start = (ci * 5) % len(pool)
    return [pool[(start + k) % len(pool)] for k in range(n)]

